#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: the real-account install test (stage 8, AC3/AC4).
#
# Sets the repository secrets .github/workflows/install-test.yml needs:
#   CF_TEST_ACCOUNT_ID   the dedicated test account's id
#   CF_TEST_API_TOKEN    an account API token scoped to that account only
# Run from the repository root: bash scripts/setup-ci-cloudflare.sh
# Nothing secret is written to disk: the token goes straight to GitHub.
# ──────────────────────────────────────────────────────────────────────────

# Local, git-ignored (.env*): remembers the account id between runs. Never the token.
ENV_FILE=".env.ci-cloudflare"

TOTAL_STAGES=6

banner "CRM: Cloudflare test account for the install test"

stage "Tools"
say "This wizard needs the GitHub CLI (signed in, with access to this repository) and curl."
if ! command -v curl >/dev/null 2>&1; then warn "curl is not installed; install it and re-run."; exit 1; fi
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  say "gh is signed in. Secrets will be set on: $(gh repo view --json nameWithOwner --jq .nameWithOwner 2>/dev/null || echo 'this repository')"
else
  warn "gh is missing or not signed in: run 'gh auth login' first, or set the two secrets by hand at the end."
fi
pause

stage "A dedicated Cloudflare account"
say "The test installs, upgrades, breaks and deletes a whole CRM, so use an account that holds"
say "nothing else. It needs the Workers Paid plan (Durable Objects with SQLite, Workflows, Worker Loader)."
open_url "https://dash.cloudflare.com/"
step "Create a new account (or pick an empty one you already have) from the account switcher."
step "In that account: Workers & Pages → Plans → subscribe to Workers Paid."
step "Workers & Pages → Overview: if asked, choose a workers.dev subdomain."
step "Copy the Account ID (Workers & Pages → Overview, right-hand column, or the URL after dash.cloudflare.com/)."
ask CF_TEST_ACCOUNT_ID "Paste the account ID:"
if [[ ! "$CF_TEST_ACCOUNT_ID" =~ ^[0-9a-f]{32}$ ]]; then warn "That doesn't look like an account ID (32 hex characters)."; exit 1; fi
write_env CF_TEST_ACCOUNT_ID "$CF_TEST_ACCOUNT_ID"

stage "An API token scoped to that account"
open_url "https://dash.cloudflare.com/${CF_TEST_ACCOUNT_ID}/api-tokens"
say "Create an account-owned token (Manage Account → Account API Tokens → Create Token → Custom token)."
say "If your dashboard has no account tokens, use My Profile → API Tokens instead, and limit it to this account."
step "Name: crm-install-test"
step "Permissions, all at Account level (the same ones docs/deploying.md lists for create-crm):"
note "    Workers Scripts           Edit"
note "    D1                        Edit"
note "    Workers R2 Storage        Edit"
note "    Workers KV Storage        Edit"
note "    Queues                    Edit"
note "    Vectorize                 Edit"
note "    Account Settings          Read"
note "    Workers AI                Read   (optional; for model roles once installed)"
step "Account Resources: Include → only this test account."
step "No zone permissions are needed: the test uses workers.dev."
step "Continue to summary → Create Token → copy the token (shown once)."
ask_secret CF_TEST_API_TOKEN "Paste the token (hidden):"
[[ -n "$CF_TEST_API_TOKEN" ]] || { warn "No token entered."; exit 1; }

stage "Check the token"
api() { curl -fsS -H "Authorization: Bearer ${CF_TEST_API_TOKEN}" "https://api.cloudflare.com/client/v4$1"; }
ok=true
if api "/accounts/${CF_TEST_ACCOUNT_ID}/tokens/verify" >/dev/null 2>&1 || api "/user/tokens/verify" >/dev/null 2>&1; then
  say "✓ token is active"
else
  warn "the token did not verify"; ok=false
fi
for check in "workers/scripts:Workers Scripts" "d1/database:D1" "r2/buckets:R2" "storage/kv/namespaces:KV" "queues:Queues" "vectorize/v2/indexes:Vectorize"; do
  path="${check%%:*}"; label="${check#*:}"
  if api "/accounts/${CF_TEST_ACCOUNT_ID}/${path}" >/dev/null 2>&1; then say "✓ $label"; else warn "$label: no access"; ok=false; fi
done
if ! $ok; then
  warn "Fix the token's permissions (or the account it is limited to) and re-run."
  confirm "Set the secrets anyway?" || exit 1
fi
pause

stage "GitHub secrets"
say "Setting the repository secrets install-test.yml reads."
set_secret CF_TEST_ACCOUNT_ID "$CF_TEST_ACCOUNT_ID"
set_secret CF_TEST_API_TOKEN "$CF_TEST_API_TOKEN"
pause

stage "First run"
say "install-test.yml runs nightly and on every release tag. It skips while there is no published release."
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1 && confirm "Start a run of the Install test workflow now?"; then
  if gh workflow run install-test.yml >/dev/null 2>&1; then
    say "Started. Watch it with: gh run watch \$(gh run list --workflow install-test.yml -L1 --json databaseId --jq '.[0].databaseId')"
  else
    warn "Couldn't start it (is install-test.yml on the default branch yet?). Run it later from the Actions tab."
  fi
fi
pause

finish
